(window.LP_CLIPS=window.LP_CLIPS||{});window.LP_CLIPS["pl"]=Object.assign(window.LP_CLIPS["pl"]||{},{"pip i bezpieczne przejście": "", "szop pip obudził się w małym miasteczku, a poranek był jasny.": "", "pip chciał zobaczyć psa, który czekał po drugiej stronie ulicy.": "", "ale ulica była głośna, samochody jechały szybko, a pip, kot i kaczka byli za mali, żeby ją przejść.": "", "pip usiadł i pomyślał. ludzie zbudowali tę ulicę, więc ludzie mogą ją zmienić.": "", "pip zapukał więc do drzwi, a sąsiedzi wyszli, żeby posłuchać.": "", "razem poprosili o bezpieczne miejsce do przejścia, a miasto się zgodziło.": "", "przyjechały koparki, przejechał walec, a robotnicy namalowali jasne pasy.": "", "teraz samochody się zatrzymują, a wszyscy przechodzą razem.": "", "pip przytulił psa. jeden mały głos i kilku dobrych przyjaciół zmieniło ulicę.": "", "świat tworzą ludzie, a ludzie mogą go uczynić życzliwszym. dobranoc, pip. dobranoc wszystkim.": ""});
